# 安装/卸载/查看 自动同步的计划任务(设备端, PowerShell 7, 不需要管理员)
#
# 用法:  pwsh scripts\sync\install_auto_sync.ps1 install|uninstall|status
#   install   建立计划任务 robot_cell_auto_sync: 每 2 分钟在后台(无窗口)运行一次 auto_sync.ps1
#   uninstall 删除这个计划任务(不删任何文件)
#   status    看任务是否存在、上次运行情况, 以及 logs\sync.log 最后 10 行
# 说明: 任务以当前登录用户运行(要用这个用户保存的 GitHub 登录), 所以需要桌面有人登录(和扫码服务一样)。

param([ValidateSet('install', 'uninstall', 'status')][string]$Action = 'status')

$Task = 'robot_cell_auto_sync'
$Root = (Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$Vbs = Join-Path $PSScriptRoot 'auto_sync_hidden.vbs'
$LogFile = Join-Path $Root 'logs\sync.log'

switch ($Action) {
    'install' {
        $tr = "wscript.exe //B //Nologo `"$Vbs`""
        schtasks /create /tn $Task /sc minute /mo 2 /tr $tr /f | Out-Null
        if ($LASTEXITCODE -ne 0) { Write-Host "[失败] 建立计划任务失败。" -ForegroundColor Red; exit 1 }
        schtasks /run /tn $Task | Out-Null
        Write-Host "[完成] 已安装: 每 2 分钟自动拉取代码; 云端要日志时自动上传。运行记录在 $LogFile" -ForegroundColor Green
    }
    'uninstall' {
        schtasks /delete /tn $Task /f | Out-Null
        if ($LASTEXITCODE -eq 0) { Write-Host "[完成] 已卸载自动同步。" -ForegroundColor Green }
        else { Write-Host "[提示] 没有找到这个计划任务(可能本来就没装)。" -ForegroundColor Yellow }
    }
    'status' {
        schtasks /query /tn $Task /fo list /v 2>$null | Select-String -Pattern '任务名|TaskName|上次运行时间|Last Run Time|上次结果|Last Result|下次运行时间|Next Run Time|模式|Status'
        if ($LASTEXITCODE -ne 0) { Write-Host "[未安装] 没有计划任务 $Task" -ForegroundColor Yellow }
        if (Test-Path $LogFile) { Write-Host "── $LogFile 最后 10 行 ──"; Get-Content $LogFile -Tail 10 -Encoding utf8 }
    }
}

