import json
f='1ee48d1d-2b0e-42df-b32a-bbfdf1a1bbd9.jsonl'
with open(f,encoding='utf-8',errors='replace') as fh:
    for i,line in enumerate(fh,1):
        if i<1946: continue
        try:o=json.loads(line)
        except Exception: continue
        if o.get('type') not in('user','assistant'): continue
        c=o.get('message',{}).get('content')
        ts=o.get('timestamp','')[:19]
        if isinstance(c,str): print(f'L{i} {o["type"]} {ts} TEXT: {c[:600]}\n'); continue
        for b in c or []:
            t=b.get('type')
            if t=='text': print(f'L{i} {o["type"]} {ts} TEXT: {b["text"][:1500]}\n')
            elif t=='tool_use': print(f'L{i} TOOL_USE: {json.dumps(b.get("input"),ensure_ascii=False)[:700]}\n')
            elif t=='tool_result':
                r=b.get('content')
                if isinstance(r,list): r=' '.join(x.get('text','') for x in r if isinstance(x,dict) and x.get('type')=='text')
                print(f'L{i} TOOL_RESULT: {str(r)[:2500]}\n')
            elif t=='image': print(f'L{i} [图片]\n')
EOF

