# -*- coding: utf-8 -*-
"""动作: 送料(feed, 2026-09-07) —— 取料台已空(视觉确认) → 放行上苗机Y1 → 等药盒落到取料台.
到达判定(两路任一, 2026-09-07下午实测定): 
  ① 斜坡传感器X1~X3亮(盒滑过, 仅亮≈40ms) → Y1停; 但此刻盒还在斜坡上滑, 再等相机看到桌面有盒(≤feeder.land_s)才算落桌
  ② 传感器漏检时: 相机每 feeder.vision_poll_s 粗定位一次, 看到盒 → force_arrived 停Y1
  传感器亮了但 land_s 内相机没看到 → 再放行推一次(最多 feeder.nudge_max 次)
入口:  取料台空(detect 报 E_NO_BOX 之后), 臂在 home(相机看桌), 上苗机服务已 start
出口:  取料台有盒(相机确认), 臂没动
失败:  E_FEEDER_OFFLINE / E_FEED_TIMEOUT(等 feeder.wait_s 未到: 料斗/中转皮带空? 人工补料)
"""
import os, sys, time
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, ROOT)
from actions.result import ActionResult, FailCategory as C, PayloadState as P, Stopwatch  # noqa: E402
from actions.speed import knob  # noqa: E402

def _sensors(feeder):
    try:
        st = feeder._ctrl.read_all_sensors()
        return " ".join("%s=%s" % (k, "●" if st.get(k) != feeder._baseline.get(k) else "○") for k in feeder._baseline)
    except Exception:
        return "-"

def _seen(vision, arm):
    """相机粗定位: 桌面上(落料带内, 斜坡上的不算)的盒数(0=无, -1=相机不可用)"""
    from actions.table_guard import count_on_table
    return count_on_table(arm, vision)

def feed(feeder, vision=None, dry=False, arm=None, abort_check=None):
    sw = Stopwatch(); act = "送料"
    if dry:
        return ActionResult(act, True, "OK", C.NONE, "仿真干跑: 跳过上苗机", P.NONE, "未动", sw.s(), {"模式": "仿真干跑"})
    if feeder is None:
        return ActionResult(act, False, "E_FEEDER_OFFLINE", C.MANUAL, "上苗机服务不在(feeder.enabled/串口)", P.NONE, "未动", sw.s())
    wait_s = float(knob("feeder", "wait_s", 30)); land_s = float(knob("feeder", "land_s", 3.0))
    poll = float(knob("feeder", "vision_poll_s", 0.5)); nudge_max = int(knob("feeder", "nudge_max", 3))
    t0 = time.time(); nudges = 0; log = []
    feeder.notify_resume(); log.append("放行@0.0s")
    t_sensor = None
    while time.time() - t0 < wait_s:
        if abort_check is not None and abort_check():
            data = {"过程": " → ".join(log) + " → 上位机立即停止"}
            return ActionResult(act, False, "E_ABORTED", C.MANUAL, "上位机立即停止(送料等待中)", P.NONE, "未动(臂在原位)", sw.s(), data)
        if t_sensor is None and feeder.box_arrived:
            t_sensor = time.time(); log.append("传感器亮@%.1fs" % (t_sensor - t0))
        n = _seen(vision, arm)
        if n > 0:
            if t_sensor is None:
                feeder.force_arrived(); log.append("相机先看到@%.1fs(传感器漏检)" % (time.time() - t0))
            else:
                log.append("相机确认落桌@%.1fs" % (time.time() - t0))
            data = {"盒数": n, "过程": " → ".join(log), "传感器": _sensors(feeder)}
            return ActionResult(act, True, "OK", C.NONE, "药盒已在取料台(%.1fs, 相机确认%d盒)" % (time.time() - t0, n), P.NONE, "未动(臂在原位)", sw.s(), data)
        if t_sensor is not None and time.time() - t_sensor > land_s:
            if nudges >= nudge_max:
                break
            nudges += 1; t_sensor = None
            feeder.notify_resume(); log.append("相机%.0fs没看到→再推@%.1fs" % (land_s, time.time() - t0))
        time.sleep(poll)
    data = {"过程": " → ".join(log), "传感器": _sensors(feeder)}
    return ActionResult(act, False, "E_FEED_TIMEOUT", C.MANUAL, "放行%.0fs仍未见药盒落桌: 料斗/中转皮带可能空了, 或相机视野问题" % (time.time() - t0),
                        P.NONE, "未动(臂在原位)", sw.s(), data)
