    Add-Content -Path $LogFile -Value ("[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $msg) -Encoding utf8
}

# 同一时间只跑一个
$mutex = New-Object System.Threading.Mutex($false, 'robot_cell_auto_sync')
if (-not $mutex.WaitOne(0)) { exit 0 }
try {
    if ((Test-Path $LogFile) -and (Get-Item $LogFile).Length -gt 1MB) {
        Set-Content -Path $LogFile -Value (Get-Content $LogFile -Tail 2000) -Encoding utf8
    }

    # ── ① 拉取代码 ──
    $cur = (git rev-parse --abbrev-ref HEAD 2>$null)
    if ($cur -ne $Branch) {
        Log "跳过拉取: 当前分支是 $cur, 不是 $Branch"
    } else {
        $before = (git rev-parse --short HEAD)
        $out = git fetch origin $Branch 2>&1
        if ($LASTEXITCODE -ne 0) {
            Log "拉取失败(连不上 GitHub): $($out | Select-Object -Last 1)"
        } else {
            $target = (git rev-parse --short FETCH_HEAD)
            if ($target -ne $before) {
                $out = git merge --ff-only FETCH_HEAD 2>&1
                if ($LASTEXITCODE -eq 0) {
                    $files = @(git diff --name-only $before $target)
                    Log "已更新 $before → $target ($($files.Count) 个文件): $(($files | Select-Object -First 8) -join ', ')"
                } else {
                    Log "无法更新到 $target (本机改动与云端冲突或有未推送提交), 代码保持 $before : $(($out | Select-Object -Last 3) -join ' | ')"
                }
            }
        }
    }

    # ── ② 云端要日志了吗 ──
    if (Test-Path $ReqFile) {
        $line = (Get-Content $ReqFile -Encoding utf8 | Where-Object { $_ -and $_ -notmatch '^\s*#' } | Select-Object -First 1)
        if ($line) {
            $parts = $line.Trim() -split '\s+', 3
            $id = $parts[0]
            $days = 2
            if ($parts.Count -ge 2) { [void][int]::TryParse($parts[1], [ref]$days) }
            $note = if ($parts.Count -ge 3) { $parts[2] } else { '' }
            $done = if (Test-Path $StateFile) { (Get-Content $StateFile -TotalCount 1) } else { $null }
            if ($null -eq $done) {
                Set-Content -Path $StateFile -Value $id -Encoding utf8    # 第一次运行: 记下当前编号, 不上传
                Log "首次运行, 记下日志请求编号 $id"
            } elseif ($done.Trim() -ne $id) {
                Log "云端请求日志(编号 $id, 最近 $days 天, 备注: $note), 开始上传"
                $out = & pwsh -NoProfile -File (Join-Path $PSScriptRoot 'push_logs.ps1') -Days $days -Note "自动#$id $note" 2>&1
                if ($LASTEXITCODE -eq 0) {
                    Set-Content -Path $StateFile -Value $id -Encoding utf8
                    Log "上传完成: $(($out | Select-Object -Last 3) -join ' | ')"
                } else {
                    Log "上传失败, 下一轮重试: $(($out | Select-Object -Last 6) -join ' | ')"
                }
            }
        }
    }
} catch {
    Log "异常: $($_.Exception.Message)"
} finally {
    $mutex.ReleaseMutex()
}
